package edu.klh.soa.shelfstock; import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;import java.util.*; @RestController @RequestMapping("/stock") public class StockController {private final StockRepository repo;public StockController(StockRepository r){repo=r;} @GetMapping public List<ShelfStock> all(){return repo.findAll();} @GetMapping("/lot/{lot}") public List<ShelfStock> lot(@PathVariable String lot){return repo.findByLotCode(lot);} @PostMapping public ResponseEntity<ShelfStock> add(@RequestBody ShelfStock s){if(s.quantity<0||s.lotCode==null||s.shelfId==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"valid shelfId, lotCode and nonnegative quantity required");return ResponseEntity.status(201).body(repo.save(s));} @PostMapping("/seed") public Map<String,Object> seed(){if(repo.count()==0){repo.save(new ShelfStock("SHELF-01","LOT-A100",12));repo.save(new ShelfStock("SHELF-02","LOT-A100",5));repo.save(new ShelfStock("SHELF-03","LOT-A101",8));repo.save(new ShelfStock("SHELF-04","LOT-B200",6));}return Map.of("seeded",true,"count",repo.count());}}